import java.io.*;
import java.util.Arrays;

public class Main {
    static final byte[] buf = new byte[1 << 16];
    static int bufLen = 0, bufPos = 0;

    static int readByte() throws IOException {
        if (bufPos == bufLen) {
            bufLen = System.in.read(buf, 0, buf.length);
            bufPos = 0;
            if (bufLen <= 0) return -1;
        }
        return buf[bufPos++];
    }

    static int readInt() throws IOException {
        int c = readByte();
        while (c != -1 && c <= ' ') c = readByte();
        int x = 0;
        while (c > ' ') {
            x = x * 10 + (c - '0');
            c = readByte();
        }
        return x;
    }

    public static void main(String[] args) throws IOException {
        int n = readInt();
        int[] values = new int[n];
        for (int i = 0; i < n; i++) values[i] = readInt();
        Arrays.sort(values);
        if (values[0] == 1) { // everything can become 1
            System.out.println(n);
            return;
        }
        // Compress to distinct values with their frequencies.
        int u = 0;
        int[] count = new int[n];
        long answer = 0;
        for (int i = 0; i < n; i++) {
            answer += values[i];
            if (u > 0 && values[u - 1] == values[i]) count[u - 1]++;
            else {
                values[u] = values[i];
                count[u++] = 1;
            }
        }
        int maximum = values[u - 1];
        // Bitmap of values that have not yet found their smallest existing divisor.
        long[] alive = new long[(maximum >>> 6) + 1];
        for (int k = 0; k < u; k++) alive[values[k] >>> 6] |= 1L << values[k];
        for (int k = 0; k < u; k++) {
            int d = values[k];
            if ((alive[d >>> 6] & (1L << d)) == 0) continue; // covered by a smaller divisor
            alive[d >>> 6] &= ~(1L << d);
            for (int multiple = d + d; multiple <= maximum; multiple += d) { // < 4e8, no int overflow
                long bit = 1L << multiple;
                if ((alive[multiple >>> 6] & bit) == 0) continue;
                alive[multiple >>> 6] &= ~bit;
                int found = Arrays.binarySearch(values, k + 1, u, multiple);
                answer -= (long) (multiple - d) * count[found];
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"slices"
	"sort"
)

func main() {
	reader := bufio.NewReaderSize(os.Stdin, 1<<16)
	readInt := func() uint32 {
		c, err := reader.ReadByte()
		for err == nil && c <= ' ' {
			c, err = reader.ReadByte()
		}
		var x uint32
		for err == nil && c > ' ' {
			x = x*10 + uint32(c-'0')
			c, err = reader.ReadByte()
		}
		return x
	}
	n := int(readInt())
	values := make([]uint32, n)
	for i := range values {
		values[i] = readInt()
	}
	slices.Sort(values)
	if values[0] == 1 { // everything can become 1
		fmt.Println(n)
		return
	}
	// Compress to distinct values with their frequencies.
	count := make([]uint32, n)
	u := 0
	var answer uint64
	for _, v := range values {
		answer += uint64(v)
		if u > 0 && values[u-1] == v {
			count[u-1]++
		} else {
			values[u] = v
			count[u] = 1
			u++
		}
	}
	values, count = values[:u], count[:u]
	maximum := values[u-1]
	// Bitmap of values that have not yet found their smallest existing divisor.
	alive := make([]uint64, maximum/64+1)
	for _, v := range values {
		alive[v>>6] |= 1 << (v & 63)
	}
	for k, d := range values {
		if alive[d>>6]&(1<<(d&63)) == 0 {
			continue // covered by a smaller divisor
		}
		alive[d>>6] &^= 1 << (d & 63)
		for m := uint64(d) * 2; m <= uint64(maximum); m += uint64(d) {
			bit := uint64(1) << (m & 63)
			if alive[m>>6]&bit == 0 {
				continue
			}
			alive[m>>6] &^= bit
			found := k + 1 + sort.Search(u-k-1, func(i int) bool { return uint64(values[k+1+i]) >= m })
			answer -= (m - uint64(d)) * uint64(count[found])
		}
	}
	fmt.Println(answer)
}
